package io.github.serenibyss.gemsack;

import com.google.common.collect.Multiset;
import com.google.common.collect.Multisets;
import com.google.inject.Provides;

import javax.inject.Inject;

import io.github.serenibyss.gemsack.render.GemSackOverlay;
import lombok.extern.slf4j.Slf4j;

import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

@Slf4j
@PluginDescriptor(
        name = "Gem Sack",
        description = "Extra info at a glance about the Gem Sack (and its earlier forms)",
        tags = {"gem", "sack", "crafting", "sapphire", "emerald", "ruby", "diamond", "dragonstone", "opal", "jade", "topaz"}
)
public class GemSackPlugin extends Plugin {

    @Inject
    private Client client;

    @Inject
    private TooltipManager tooltipManager;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private ConfigManager configManager;

    @Inject
    private GemSackConfig config;

    private GemSackOverlay overlay = null;

    // For when the sack is used on an item, or an item is used on the sack, or the sack is emptied to bank
    private Multiset<Integer> inventorySnapshot;
    private final List<SackTypes> clickedSacks = new ArrayList<>();
    private boolean checkForUpdate;

    // For when the "Check" message is clicked on a sack
    private SackTypes checkedSack;

    // For when the "Empty containers" button is clicked in a bank
    private final List<SackTypes> emptiedSacks = new ArrayList<>();

    // For when a gem is picked up off the ground
    private GemTypes pickedUpGem;

    // For when a gem is telegrabbed
    private GemTypes telegrabbedGem;

    @Override
    protected void startUp() throws Exception {
        overlay = new GemSackOverlay(config, client, tooltipManager);
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown() throws Exception {
        overlayManager.remove(overlay);
    }

    @Provides
    GemSackConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(GemSackConfig.class);
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGGED_IN) {
            for (SackTypes sackType : SackTypes.values()) {
                sackType.getStorage().load(configManager);
            }
        }
    }

    @Subscribe
    public void onItemDespawned(ItemDespawned event) {
        if (event.getItem() == null) return;

        if (pickedUpGem != null) {
            if (event.getItem().getId() != pickedUpGem.getItemID()) return;
            handlePickedUpGem(pickedUpGem);
            pickedUpGem = null;
        }

        if (telegrabbedGem != null) {
            if (event.getItem().getId() != telegrabbedGem.getItemID()) return;
            handlePickedUpGem(telegrabbedGem);
            telegrabbedGem = null;
        }
    }

    private void handlePickedUpGem(GemTypes gem) {
        ItemContainer playerInv = client.getItemContainer(InventoryID.INV);
        List<SackTypes> sackTypes = Utils.getOpenSacksInInventory(playerInv);
        if (sackTypes != null) {
            for (SackTypes type : sackTypes) {
                type.getStorage().addSingle(gem, configManager);
            }
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event) {
        String option = event.getMenuOption();

        // On the ground, can only pick up one ground item per tick so take the first.
        // The game tick event will clear this state for the next tick's gem if necessary.
        if (pickedUpGem == null && option.equals("Take") && GemTypes.isGemName(event.getMenuTarget())) {
            pickedUpGem = GemTypes.getGemByName(event.getMenuTarget());
        }

        // Similar to the above, except for when Telegrab is used.
        if (telegrabbedGem == null
                && option.equals("Cast")
                && event.getMenuTarget().contains("Telekinetic Grab")
                && GemTypes.isGemName(event.getMenuTarget())) {
            telegrabbedGem = GemTypes.getGemByName(event.getMenuTarget());
        }

        if (event.getWidget() == null) return;

        int id = event.getWidget().getItemId();


        // In inventory
        // Right click empty into bank
        if (SackTypes.isSackType(id)
                && (option.equals("Empty") || option.equals("Empty-to-bank") || option.equals("Fill"))) {

            // For emptying into inventory
            inventorySnapshot = Utils.createInventorySnapshot(client.getItemContainer(InventoryID.INV));
            clickedSacks.add(SackTypes.getSackType(id));
            checkForUpdate = true;

            // For emptying into bank
            checkedSack = SackTypes.getSackType(id);
        }
        // Use gem on sack thing or sack thing on gem
        else if (option.equals("Use")
                && event.getMenuAction() == MenuAction.WIDGET_TARGET_ON_WIDGET
                && client.getSelectedWidget() != null) {

            int selectedItemID = client.getSelectedWidget().getItemId();
            int clickedOnItemID = event.getWidget().getItemId();

            // Clicked gem thing onto a gem
            if (SackTypes.isSackType(selectedItemID)) {
                SackTypes sackType = SackTypes.getSackType(selectedItemID);
                List<Integer> allowedGems = sackType.getAllowedGems();
                if (allowedGems.contains(clickedOnItemID)) {
                    inventorySnapshot = Utils.createInventorySnapshot(client.getItemContainer(InventoryID.INV));
                    clickedSacks.add(sackType);
                    checkForUpdate = true;
                }
            }
            // Clicked a gem onto gem thing
            else if (SackTypes.isSackType(clickedOnItemID)) {
                SackTypes sackType = SackTypes.getSackType(clickedOnItemID);
                List<Integer> allowedGems = sackType.getAllowedGems();
                if (allowedGems.contains(selectedItemID)) {
                    inventorySnapshot = Utils.createInventorySnapshot(client.getItemContainer(InventoryID.INV));
                    clickedSacks.add(sackType);
                    checkForUpdate = true;
                }
            }
        // Empty containers button in the bank
        } else if (option.equals("Empty containers")) {
            List<SackTypes> sacks = Utils.getSacksInInventory(client.getItemContainer(InventoryID.INV), true);
            if (sacks != null) {
                emptiedSacks.addAll(sacks);
            }
        }
        // Fallback, if the gem sack is checked, read the text
        else if (SackTypes.isSackType(id) && option.equals("Check")) {
            checkedSack = SackTypes.getSackType(id);
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        // Gem rock mining
        if (event.getType() == ChatMessageType.SPAM) {
            String message = event.getMessage();
            // "mined": gem rocks, "found": other mining sources
            if (message.startsWith("You just mined a") || message.startsWith("You just found a")) {
                GemTypes gemType = GemTypes.getGemByName(message + "uncut"); // hacky once again
                if (gemType != null) {
                    List<SackTypes> sacks = Utils.getOpenSacksInInventory(client.getItemContainer(InventoryID.INV));
                    if (sacks != null) {
                        for (SackTypes sack : sacks) {
                            sack.getStorage().addSingle(gemType, configManager);
                        }
                    }
                }
            }
        }

        if (event.getType() == ChatMessageType.GAMEMESSAGE && checkedSack != null) {
            String message = event.getMessage();

            if (checkedSack != null) {
                if (message.startsWith("You empty your gem") && message.contains("into the bank")) {
                    checkedSack.getStorage().clear(configManager);
                }

                // Update state based on what the chat says
                if (message.startsWith("Opal:") || message.startsWith("Sapphires:")) {
                    Map<GemTypes, Integer> newGems = Utils.getGemsFromChat(message);
                    checkedSack.getStorage().forceUpdate(newGems, configManager);
                }

                // Emergency exit if the bag gets a messed up state
                if (message.startsWith("The gem") && (message.contains("is now empty.") || message.contains("is empty."))) {
                    checkedSack.getStorage().clear(configManager);
                }

                checkedSack = null;
            }

            if (!emptiedSacks.isEmpty()) {
                if (message.equals("You empty all of your containers into the bank.")) {
                    emptiedSacks.forEach(sack -> sack.getStorage().clear(configManager));
                }

                // Emergency exit if the bag gets a messed up state
                if (message.equals("Your containers are already empty.")) {
                    emptiedSacks.forEach(sack -> sack.getStorage().clear(configManager));
                }

                emptiedSacks.clear();
            }
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event) {
        if (event.getContainerId() != InventoryID.INV) return;

        if (checkForUpdate) {
            checkForUpdate = false;
            SackTypes[] sacks = clickedSacks.toArray(new SackTypes[0]);
            clickedSacks.clear();

            Multiset<Integer> currentInventory = Utils.createInventorySnapshot(event.getItemContainer());
            Multiset<Integer> deltaMinus = Multisets.difference(currentInventory, inventorySnapshot);
            Multiset<Integer> deltaPlus = Multisets.difference(inventorySnapshot, currentInventory);
            for (SackTypes sackType : sacks) {
                sackType.getStorage().update(deltaMinus, deltaPlus, configManager);
            }
        }
    }
}

package io.github.serenibyss.gemsack.render;

import io.github.serenibyss.gemsack.SackTypes;

import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.FontManager;

import java.awt.*;

public class GemSackTextOverlay {

    void draw(Graphics2D graphics, WidgetItem widgetItem, SackTypes sackType) {
        graphics.setFont(FontManager.getRunescapeFont());
        int stored = sackType.getStorage().getTotalStored();

        int startDrawX = widgetItem.getCanvasLocation().getX();
        int startDrawY = widgetItem.getCanvasLocation().getY() + 31;

        drawString(graphics, FontManager.getRunescapeSmallFont(), "" + stored, startDrawX, startDrawY);
    }

    private void drawString(Graphics2D graphics, Font font, String label, int x, int y) {
        graphics.setFont(font);
        graphics.setColor(Color.BLACK);
        graphics.drawString(label, x + 1, y + 1);
        graphics.setColor(Color.WHITE);
        graphics.drawString(label, x, y);
    }
}

package io.github.serenibyss.gemsack.render;

import io.github.serenibyss.gemsack.GemSackConfig;
import io.github.serenibyss.gemsack.SackTypes;
import lombok.extern.slf4j.Slf4j;

import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

import java.awt.*;

@Slf4j
public class GemSackOverlay extends WidgetItemOverlay {

    private final Client client;
    private final GemSackConfig config;

    // Renderers
    private final GemSackTextOverlay overlay;
    private final GemSackTooltip tooltip;

    public GemSackOverlay(GemSackConfig config, Client client, TooltipManager tooltipManager) {
        this.config = config;
        this.client = client;

        showOnInventory();

        this.overlay = new GemSackTextOverlay();
        this.tooltip = new GemSackTooltip(tooltipManager);
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem) {
        SackTypes sackType = SackTypes.getSackType(itemId);
        if (sackType == null) return;

        graphics.setFont(FontManager.getRunescapeSmallFont());

        if (sackType.enableOverlay(this.config)) {
            overlay.draw(graphics, widgetItem, sackType);
        }

        if (sackType.enableHover(this.config) && isHovered(widgetItem, client.getMouseCanvasPosition())) {
            tooltip.renderTooltip(sackType);
        }
    }

    private boolean isHovered(WidgetItem widgetItem, Point mousePosition) {
        return widgetItem.getCanvasBounds().contains(mousePosition.getX(), mousePosition.getY());
    }
}

package io.github.serenibyss.gemsack.render;

import io.github.serenibyss.gemsack.SackStorage;
import io.github.serenibyss.gemsack.SackTypes;

import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;

import java.awt.*;

public class GemSackTooltip {

    private static final String BR = "</br>";

    private final TooltipManager tooltipManager;

    public GemSackTooltip(TooltipManager tooltipManager) {
        this.tooltipManager = tooltipManager;
    }

    void renderTooltip(SackTypes sackType) {
        SackStorage storage = sackType.getStorage();

        int brLength = 0;
        StringBuilder tb = new StringBuilder();

        if (storage.isEmpty()) {
            tooltipManager.add(new Tooltip("Empty"));
            return;
        }

        tb.append(storage.getOpal() > 0 ? "Uncut opal: " + color(String.valueOf(storage.getOpal())) : "");
        if (tb.length() > brLength) {
            tb.append(BR);
            brLength = tb.length();
        }

        tb.append(storage.getJade() > 0 ? "Uncut jade: " + color(String.valueOf(storage.getJade())) : "");
        if (tb.length() > brLength) {
            tb.append(BR);
            brLength = tb.length();
        }

        tb.append(storage.getTopaz() > 0 ? "Uncut red topaz: " + color(String.valueOf(storage.getTopaz())) : "");
        if (tb.length() > brLength) {
            tb.append(BR);
            brLength = tb.length();
        }

        tb.append(storage.getSapphire() > 0 ? "Uncut sapphire: " + color(String.valueOf(storage.getSapphire())) : "");
        if (tb.length() > brLength) {
            tb.append(BR);
            brLength = tb.length();
        }

        tb.append(storage.getEmerald() > 0 ? "Uncut emerald: " + color(String.valueOf(storage.getEmerald())) : "");
        if (tb.length() > brLength) {
            tb.append(BR);
            brLength = tb.length();
        }

        tb.append(storage.getRuby() > 0 ? "Uncut ruby: " + color(String.valueOf(storage.getRuby())) : "");
        if (tb.length() > brLength) {
            tb.append(BR);
            brLength = tb.length();
        }

        tb.append(storage.getDiamond() > 0 ? "Uncut diamond: " + color(String.valueOf(storage.getDiamond())) : "");
        if (tb.length() > brLength) {
            tb.append(BR);
        }

        tb.append(storage.getDragonstone() > 0 ? "Uncut dragonstone: " + color(String.valueOf(storage.getDragonstone())) : "");
        tooltipManager.add(new Tooltip(tb.toString()));
    }

    private static String color(String text) {
        return ColorUtil.wrapWithColorTag(text, ColorUtil.fromHex("FF9040"));
    }
}

package io.github.serenibyss.gemsack;

import lombok.Getter;

import net.runelite.api.gameval.ItemID;

import java.util.Arrays;
import java.util.List;

public enum SackTypes {

    POUCH(ItemID.GEM_POUCH, ItemID.GEM_POUCH_OPEN, 5),
    SATCHEL(ItemID.GEM_SATCHEL, ItemID.GEM_SATCHEL_OPEN, 10),
    TOTE(ItemID.GEM_TOTE, ItemID.GEM_TOTE_OPEN, 20),
    BAG(ItemID.GEM_BAG, ItemID.GEM_BAG_OPEN, 60),
    SACK(ItemID.GEM_SACK, ItemID.GEM_SACK_OPEN, 60);

    private static final List<Integer> BASIC_GEMS = Arrays.asList(
            ItemID.UNCUT_SAPPHIRE,
            ItemID.UNCUT_EMERALD,
            ItemID.UNCUT_RUBY,
            ItemID.UNCUT_DIAMOND,
            ItemID.UNCUT_DRAGONSTONE);

    private static final List<Integer> WEIRD_GEMS = Arrays.asList(
            ItemID.UNCUT_OPAL,
            ItemID.UNCUT_JADE,
            ItemID.UNCUT_RED_TOPAZ);

    private static final List<Integer> ALL_GEMS = Arrays.asList(
            ItemID.UNCUT_OPAL,
            ItemID.UNCUT_JADE,
            ItemID.UNCUT_RED_TOPAZ,
            ItemID.UNCUT_SAPPHIRE,
            ItemID.UNCUT_EMERALD,
            ItemID.UNCUT_RUBY,
            ItemID.UNCUT_DIAMOND,
            ItemID.UNCUT_DRAGONSTONE);

    private static final List<String> BASIC_GEM_NAMES = Arrays.asList(
            "Uncut sapphire",
            "Uncut emerald",
            "Uncut ruby",
            "Uncut diamond",
            "Uncut dragonstone");

    private static final List<String> WEIRD_GEM_NAMES = Arrays.asList(
            "Uncut opal",
            "Uncut jade",
            "Uncut red topaz");

    private static final List<String> ALL_GEM_NAMES = Arrays.asList(
            "Uncut opal",
            "Uncut jade",
            "Uncut red topaz",
            "Uncut sapphire",
            "Uncut emerald",
            "Uncut ruby",
            "Uncut diamond",
            "Uncut dragonstone");

    @Getter
    private final int closedItemID;
    @Getter
    private final int openItemID;
    @Getter
    private final int maxGems;
    @Getter
    private final SackStorage storage;

    SackTypes(int closedItemID, int openItemID, int maxGems) {
        this.closedItemID = closedItemID;
        this.openItemID = openItemID;
        this.maxGems = maxGems;
        this.storage = new SackStorage(this);
    }

    public boolean enableHover(GemSackConfig config) {
        switch (this) {
            case POUCH: return config.gemPouchHover();
            case SATCHEL: return config.gemSatchelHover();
            case TOTE: return config.gemToteHover();
            case BAG: return config.gemBagHover();
            case SACK: return config.gemSackHover();
            default: return false;
        }
    }

    public boolean enableOverlay(GemSackConfig config) {
        switch (this) {
            case POUCH: return config.gemPouchOverlay();
            case SATCHEL: return config.gemSatchelOverlay();
            case TOTE: return config.gemToteOverlay();
            case BAG: return config.gemBagOverlay();
            case SACK: return config.gemSackOverlay();
            default: return false;
        }
    }

    public List<Integer> getAllowedGems() {
        switch (this) {
            case POUCH:
            case SATCHEL:
            case TOTE:
                return WEIRD_GEMS;
            case BAG:
                return BASIC_GEMS;
            case SACK:
                return ALL_GEMS;
            default:
                return null;
        }
    }

    public boolean canStoreGem(int gemItemID) {
        List<Integer> allowedGems = getAllowedGems();
        if (allowedGems == null) return false;
        return allowedGems.contains(gemItemID);
    }

    public boolean canStoreGem(GemTypes gemType) {
        return canStoreGem(gemType.getItemID());
    }

    public List<String> getAllowedGemNames() {
        switch (this) {
            case POUCH:
            case SATCHEL:
            case TOTE:
                return WEIRD_GEM_NAMES;
            case BAG:
                return BASIC_GEM_NAMES;
            case SACK:
                return ALL_GEM_NAMES;
            default:
                return null;
        }
    }

    public static SackTypes getSackType(int itemID) {
        if (itemID == POUCH.getClosedItemID() || itemID == POUCH.getOpenItemID()) {
            return POUCH;
        } else if (itemID == SATCHEL.getClosedItemID() || itemID == SATCHEL.getOpenItemID()) {
            return SATCHEL;
        } else if (itemID == TOTE.getClosedItemID() || itemID == TOTE.getOpenItemID()) {
            return TOTE;
        } else if (itemID == BAG.getClosedItemID() || itemID == BAG.getOpenItemID()) {
            return BAG;
        } else if (itemID == SACK.getClosedItemID() || itemID == SACK.getOpenItemID()) {
            return SACK;
        }
        return null;
    }

    public static boolean isSackType(int itemID) {
        return getSackType(itemID) != null;
    }

    public static List<Integer> getAllGemTypes() {
        return ALL_GEMS;
    }
}

package io.github.serenibyss.gemsack;

import lombok.Getter;

import net.runelite.api.gameval.ItemID;

public enum GemTypes {

    OPAL(ItemID.UNCUT_OPAL, "opal", "opals"),
    JADE(ItemID.UNCUT_JADE, "jade", "jades"),
    TOPAZ(ItemID.UNCUT_RED_TOPAZ, "red topaz", "red topazes"),
    SAPPHIRE(ItemID.UNCUT_SAPPHIRE, "sapphire", "sapphires"),
    EMERALD(ItemID.UNCUT_EMERALD, "emerald", "emeralds"),
    RUBY(ItemID.UNCUT_RUBY, "ruby", "rubies"),
    DIAMOND(ItemID.UNCUT_DIAMOND, "diamond", "diamonds"),
    DRAGONSTONE(ItemID.UNCUT_DRAGONSTONE, "dragonstone", "dragonstones");

    private static final GemTypes[] VALUES = values();

    @Getter
    private final int itemID;
    @Getter
    private final String singularName;
    @Getter
    private final String pluralName;

    GemTypes(int itemID, String singularName, String pluralName) {
        this.itemID = itemID;
        this.singularName = singularName;
        this.pluralName = pluralName;
    }

    public boolean isGemByName(String name) {
        name = name.toLowerCase();
        if (!name.contains("uncut")) return false;
        return name.contains(singularName) || name.contains(pluralName);
    }

    public static boolean isGemName(String name) {
        return getGemByName(name) != null;
    }

    public static GemTypes getGemByName(String name) {
        for (GemTypes type : VALUES) {
            if (type.isGemByName(name)) return type;
        }
        return null;
    }

    public static GemTypes getGemByID(int itemID) {
        for (GemTypes type : VALUES) {
            if (itemID == type.itemID) return type;
        }
        return null;
    }
}

package io.github.serenibyss.gemsack;

import com.google.common.collect.HashMultiset;
import com.google.common.collect.Multiset;

import net.runelite.api.Item;
import net.runelite.api.ItemContainer;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Utils {

    public static Map<GemTypes, Integer> getGemsFromChat(String text) {
        Map<GemTypes, Integer> gems = new HashMap<>();

        try {
            text = text.replace("<br>", " / ");
            String[] entries = text.split("\\s*/\\s*");
            for (String entry : entries) {
                String[] parts = entry.split(":\\s*");
                if (parts.length == 2) {
                    String gem = parts[0].trim();
                    int count = Integer.parseInt(parts[1].trim());
                    GemTypes gemType = GemTypes.getGemByName("uncut " + gem); // hacky
                    if (gemType != null) {
                        gems.put(gemType, count);
                    }
                }
            }
        } catch (Throwable ignored) {}

        return gems;
    }

    // Creates a snapshot of all gems in the player's inventory when called
    public static Multiset<Integer> createInventorySnapshot(ItemContainer container) {
        if (container == null) return null;

        Multiset<Integer> inventory = HashMultiset.create();
        Arrays.stream(container.getItems())
                .filter(item -> SackTypes.getAllGemTypes().contains(item.getId()))
                .forEach(i -> inventory.add(i.getId(), i.getQuantity()));
        return inventory;
    }

    public static List<SackTypes> getOpenSacksInInventory(ItemContainer container) {
        return getSacksInInventory(container, false);
    }

    // Finds all gem sacks in the player's inventory
    // Could be multiple, if sacks are not combined to the final Gem Sack yet
    public static List<SackTypes> getSacksInInventory(ItemContainer container, boolean allowClosed) {
        if (container == null) return null;

        List<SackTypes> sacks = new ArrayList<>();
        for (Item item : container.getItems()) {
            if (item == null) continue;
            SackTypes sackType = SackTypes.getSackType(item.getId());
            if (sackType != null && (allowClosed || sackType.getOpenItemID() == item.getId())) {
                sacks.add(sackType);
            }
        }
        return sacks;
    }
}

